// m20p — Grok-concept first-person art for the eight non-sword floor weapons.
// Source: concept20 i_*.jpg (and a void recolor of the Stormspire), run through the same
// keymask/despill/quantize/outline pipeline as the in-game swords, composited on locked grips.
// Root cause of the m20n "sword outlines": glowOf, edgesOf, sheen/PTS and wpnFX were
// still keyed to the borrowed sword sprite names (vm_sword_rapier, vm_sword_storm, …),
// so a cached sword-shaped halo was drawn over the new heads. This pass points SWSPR
// at unique names (vm_m20_*) so every glow, trail sheen, enchant, smear and hit flash
// is built from the weapon's own silhouette. Effects still always draw.
// Censer flail and net-trident hide the right-hand sword while the whip is out, so they
// are held as flail/net, not as sword + offhand. Leather/fire/chain/blood whips, all
// crossbows, the Consecrated Sidearm and every real sword are left untouched.
// Hands / gauntlet pixels are never edited. No balance changes.
// Kill: ?wpnart3=0  or master ?m20p=0  (also honours ?m20=0). When on, m20o/m20n art swaps are disabled.
(function () {
  const off = /[?&](wpnart3=0|m20p=0|m20=0)(?:&|$)/.test(location.search);
  const M20P = window.M20P = { on: !off, ready: false, errs: [] };
  M20P.st = function () { return { on: M20P.on, ready: M20P.ready, wpnart3: M20P.on, errs: M20P.errs.slice(0, 5) }; };
  if (off) return;
  // Take over from m20n so we don't also swap the borrowed sword keys (that reintroduces the cache leak).
  if (window.M20N) M20N.on = false;
  if (window.M20O) M20O.on = false;

  const PAYLOAD = {"trident":{"spr":"","glow":"","sheen":""},"halberd":{"spr":"","glow":"","sheen":""},"voidhal":{"spr":"","glow":"","sheen":""},"spade":{"spr":"","glow":"","sheen":""},"maul":{"spr":"","glow":"","sheen":""},"hammer":{"spr":"","glow":"","sheen":""},"net":{"spr":"","glow":"","sheen":""},"censer":{"spr":"","glow":"","sheen":"","tip":"","tipglow":""}};

  function canvFromB64(b64, cb) {
    const im = new Image();
    im.onload = function () {
      const c = document.createElement('canvas'); c.width = im.width; c.height = im.height;
      const x = c.getContext('2d'); x.drawImage(im, 0, 0);
      const d = x.getImageData(0, 0, c.width, c.height);
      cb({ img: c, tex: { w: c.width, h: c.height, d: new Uint32Array(d.data.buffer) } });
    };
    im.onerror = function () { M20P.errs.push('artload'); cb(null); };
    im.src = 'data:image/png;base64,' + b64;
  }

  const KEYS = ['trident', 'halberd', 'voidhal', 'spade', 'maul', 'hammer', 'net', 'censer'];
  const ART = M20P.art = {};
  let left = KEYS.length * 3 + 2; // + censer tip + tipglow
  function one() {
    if (--left) return;
    M20P.ready = true;
    hook();
  }
  KEYS.forEach(function (k) {
    ART[k] = {};
    ['spr', 'glow', 'sheen'].forEach(function (slot) {
      canvFromB64(PAYLOAD[k][slot], function (r) {
        if (r) {
          let name;
          if (k === 'censer') name = 'vm_m20p_censerhandle' + (slot === 'spr' ? '' : '_' + slot);
          else if (k === 'net') name = 'vm_m20p_nethandle' + (slot === 'spr' ? '' : '_' + slot);
          else name = 'vm_m20p_' + k + (slot === 'spr' ? '' : '_' + slot);
          if (typeof Engine !== 'undefined') { Engine.imgs[name] = r.img; Engine.tex[name] = r.tex; }
          ART[k][slot] = r;
          ART[k][slot + 'Name'] = name;
        }
        one();
      });
    });
  });
  canvFromB64(PAYLOAD.censer.tip, function (r) {
    if (r) {
      if (typeof Engine !== 'undefined') { Engine.imgs['vm_m20p_censertip'] = r.img; Engine.tex['vm_m20p_censertip'] = r.tex; }
      ART.censer = ART.censer || {};
      ART.censer.tip = r;
    }
    one();
  });
  canvFromB64(PAYLOAD.censer.tipglow, function (r) {
    if (r) {
      if (typeof Engine !== 'undefined') { Engine.imgs['vm_m20p_censertip_glow'] = r.img; Engine.tex['vm_m20p_censertip_glow'] = r.tex; }
      ART.censer = ART.censer || {};
      ART.censer.tipglow = r;
    }
    one();
  });

  function current() {
    if (!M20P.on || !M20P.ready || typeof P === 'undefined' || !P || !P.mods || !P.wpn) return null;
    const m = P.mods, w = P.wpn;
    if (m.m20trident && w.sword === 'rapier') return { k: 'trident', kind: 'sword', view: 'rapier' };
    if (m.voidhal && w.sword === 'storm') return { k: 'voidhal', kind: 'sword', view: 'storm' };
    if (m.m20halberd && w.sword === 'storm') return { k: 'halberd', kind: 'sword', view: 'storm' };
    if (m.m20spade && w.sword === 'axe') return { k: 'spade', kind: 'sword', view: 'axe' };
    if (m.m20maul && w.sword === 'great') return { k: 'maul', kind: 'sword', view: 'great' };
    if (m.m20forge && w.sword === 'fire') return { k: 'hammer', kind: 'sword', view: 'fire' };
    if (m.m20net && w.whip === 'chain') return { k: 'net', kind: 'whip', view: 'chain', handle: 'vm_lwhandle_chain', hglow: 'vm_lwhip_chain_glow' };
    if (m.m20censer && w.whip === 'fire') return { k: 'censer', kind: 'whip', view: 'fire', handle: 'vm_lwhandle_fire', hglow: 'vm_lwhip_fire_glow' };
    return null;
  }
  M20P.current = current;

  function sprNames(c) {
    const a = ART[c.k];
    if (!a || !a.sprName) return null;
    return [a.sprName, a.glowName, a.sheenName];
  }

  function isSwordImg(img) {
    if (!img) return false;
    if (img._src && String(img._src).indexOf('vm_sword') === 0) return true;
    const E = (typeof Engine !== 'undefined') && Engine.imgs;
    if (!E) return false;
    for (const k in E) {
      if (k.indexOf('vm_sword') === 0 && E[k] === img) return true;
    }
    return false;
  }

  function drawCenserTip(ctx, p) {
    const x = Math.round(p[0]), y = Math.round(p[1]);
    const tip = ART.censer && ART.censer.tip && ART.censer.tip.img;
    const glow = ART.censer && ART.censer.tipglow && ART.censer.tipglow.img;
    ctx.save();
    if (tip) {
      const w = tip.width, h = tip.height;
      if (glow) {
        ctx.globalAlpha = 0.7;
        ctx.drawImage(glow, x - (w >> 1) - 1, y - Math.round(h * 0.72) - 1);
        ctx.globalAlpha = 1;
      }
      ctx.drawImage(tip, x - (w >> 1), y - Math.round(h * 0.72));
      ctx.restore();
      return;
    }
    // fallback if the tip image failed to load
    ctx.fillStyle = '#3a2008';
    ctx.fillRect(x - 3, y - 16, 7, 3);
    ctx.fillStyle = '#ffe08a';
    ctx.fillRect(x - 2, y - 15, 5, 1);
    ctx.fillStyle = '#2a1808'; ctx.fillRect(x - 7, y - 13, 15, 4);
    ctx.fillStyle = '#c89628'; ctx.fillRect(x - 6, y - 12, 13, 3);
    ctx.fillStyle = '#20c050'; ctx.fillRect(x - 4, y - 2, 9, 8);
    ctx.restore();
  }

  function drawNetBag(ctx, pts) {
    if (!pts || pts.length < 4) return;
    const n = pts.length, i0 = Math.max(2, (n * 0.48) | 0);
    ctx.save();
    // mesh widening toward the tip
    let prevL = null, prevR = null;
    for (let i = i0; i < n; i++) {
      const s = (i - i0) / Math.max(1, n - 1 - i0);
      const w = 2 + 16 * s * s;
      const p = pts[i], q = pts[Math.max(i0, i - 1)];
      const dx = p[0] - q[0], dy = p[1] - q[1], L = Math.hypot(dx, dy) || 1;
      const nx = -dy / L, ny = dx / L;
      const lx = p[0] + nx * w, ly = p[1] + ny * w, rx = p[0] - nx * w, ry = p[1] - ny * w;
      ctx.strokeStyle = (i % 2) ? 'rgba(210,190,110,0.85)' : 'rgba(90,70,36,0.9)';
      ctx.lineWidth = 1;
      if (prevL) {
        ctx.beginPath(); ctx.moveTo(prevL[0], prevL[1]); ctx.lineTo(lx, ly); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(prevR[0], prevR[1]); ctx.lineTo(rx, ry); ctx.stroke();
      }
      if (i % 2 === 0) {
        ctx.beginPath(); ctx.moveTo(lx, ly); ctx.lineTo(rx, ry); ctx.stroke();
      }
      prevL = [lx, ly]; prevR = [rx, ry];
    }
    // lead weights at the rim
    if (prevL && prevR) {
      const tip = pts[n - 1];
      const wts = [prevL, prevR, [(prevL[0] + prevR[0]) / 2, (prevL[1] + prevR[1]) / 2 + 3], [tip[0], tip[1] + 2]];
      for (const q of wts) {
        const qx = q[0] | 0, qy = q[1] | 0;
        ctx.fillStyle = '#2a2a30'; ctx.fillRect(qx - 2, qy - 1, 4, 3);
        ctx.fillStyle = '#8a8a98'; ctx.fillRect(qx - 1, qy - 1, 2, 2);
      }
    }
    ctx.restore();
  }

  function overlayPts(ctx, pts) {
    const c = current();
    if (!c || !pts || !pts.length) return;
    try {
      if (c.k === 'net') drawNetBag(ctx, pts);
      if (c.k === 'censer') drawCenserTip(ctx, pts[pts.length - 1]);
    } catch (e) { M20P.errs.push('tip'); }
  }

  function hook() {
    if (typeof drawViewModel !== 'function') { M20P.errs.push('no-dvm'); return; }
    const _dvm = drawViewModel;
    drawViewModel = function (ctx, cam) {
      const c = current();
      if (!c) return _dvm.apply(this, arguments);

      const prevSpr = (c.kind === 'sword' && typeof SWSPR !== 'undefined' && c.view) ? SWSPR[c.view] : null;
      const names = sprNames(c);
      if (c.kind === 'sword' && prevSpr && names) {
        SWSPR[c.view] = [names[0], names[1]];
      }

      // whip-slot uniques: swap only the handle/glow images for this frame (unique WFX name below)
      const keep = [];
      function put(name, img, tex) {
        if (!name || !img) return;
        keep.push([name, Engine.imgs[name], Engine.tex[name]]);
        Engine.imgs[name] = img;
        if (tex) Engine.tex[name] = tex;
      }
      if (c.kind === 'whip' && ART[c.k]) {
        put(c.handle, ART[c.k].spr && ART[c.k].spr.img, ART[c.k].spr && ART[c.k].spr.tex);
        put(c.hglow, ART[c.k].glow && ART[c.k].glow.img, ART[c.k].glow && ART[c.k].glow.tex);
      }

      const hideSword = c.kind === 'whip' && P.off === 'whip' && !P.pistol;
      const _dr = hideSword ? drawRot : null;
      const _wfx = hideSword && typeof wpnFX === 'function' ? wpnFX : null;
      const _sb = hideSword && typeof stormBlade === 'function' ? stormBlade : null;
      const _rb = hideSword && typeof rapierBlade === 'function' ? rapierBlade : null;
      const _fb = hideSword && typeof frostBlade === 'function' ? frostBlade : null;
      const _tip = hideSword && typeof tipOf === 'function' ? tipOf : null;
      if (hideSword) {
        drawRot = function (ctx2, img) {
          if (isSwordImg(img)) return;
          return _dr.apply(this, arguments);
        };
        if (_wfx) wpnFX = function () {};
        if (_sb) stormBlade = function () {};
        if (_rb) rapierBlade = function () {};
        if (_fb) frostBlade = function () {};
        if (_tip) tipOf = function (p) { return [p[0], p[1]]; };
      }

      const _wh = (c.kind === 'whip' && window.WFX && typeof WFX.whipHandle === 'function') ? WFX.whipHandle : null;
      if (_wh && names) {
        WFX.whipHandle = function (ctx2, imgName, hx, hy, hr, wsc, lash) {
          return _wh.call(this, ctx2, names[0], hx, hy, hr, wsc, lash);
        };
      }

      try { return _dvm.apply(this, arguments); }
      finally {
        if (prevSpr) SWSPR[c.view] = prevSpr;
        for (let i = 0; i < keep.length; i++) {
          const k = keep[i]; Engine.imgs[k[0]] = k[1]; Engine.tex[k[0]] = k[2];
        }
        if (_dr) drawRot = _dr;
        if (_wfx) wpnFX = _wfx;
        if (_sb) stormBlade = _sb;
        if (_rb) rapierBlade = _rb;
        if (_fb) frostBlade = _fb;
        if (_tip) tipOf = _tip;
        if (_wh) WFX.whipHandle = _wh;
      }
    };

    if (typeof bloodyBlade === 'function') {
      const _bb = bloodyBlade;
      bloodyBlade = function (name) {
        const c = current();
        if (c && c.kind === 'sword') {
          const n = sprNames(c);
          if (n) name = n[0];
        }
        return _bb(name);
      };
    }

    if (window.WFX) {
      if (typeof WFX.lash === 'function') {
        const _l = WFX.lash;
        WFX.lash = function (ctx, pts, wt) { const r = _l.apply(this, arguments); overlayPts(ctx, pts); return r; };
      }
      if (typeof WFX.coil === 'function') {
        const _c = WFX.coil;
        WFX.coil = function (ctx, pts, col, t) { const r = _c.apply(this, arguments); overlayPts(ctx, pts); return r; };
      }
    }
    if (typeof chainCord === 'function') {
      const _cc = chainCord;
      chainCord = function (ctx, pts, amt) {
        const r = _cc.apply(this, arguments);
        if (current() && current().k === 'net') overlayPts(ctx, pts);
        return r;
      };
    }
    if (typeof fireCord === 'function') {
      const _fc = fireCord;
      fireCord = function (ctx, pts, amt) {
        const r = _fc.apply(this, arguments);
        if (current() && current().k === 'censer') overlayPts(ctx, pts);
        return r;
      };
    }
    if (typeof drawCoil === 'function') {
      const _dc = drawCoil;
      drawCoil = function (ctx, top, hx, hy, cv, t, reeling) {
        const r = _dc.apply(this, arguments);
        try {
          const cur = current();
          if (!cur) return r;
          const C = [hx + 54 + 6 * (1 - cv), hy + 4 + 4 * (0.35 + 0.65 * cv)];
          if (cur.k === 'censer') drawCenserTip(ctx, [C[0], C[1] + 18 * cv]);
          if (cur.k === 'net') overlayPts(ctx, [top, [C[0], C[1] + 8], [C[0] + 6, C[1] + 16 * cv]]);
        } catch (e) { M20P.errs.push('coil'); }
        return r;
      };
    }
  }
})();
